const contextChallengeQuestion=challengeQuestion;challengeQuestion=function(item){const q=contextChallengeQuestion(item);if(item.id!=='famouspeople')return q;const p=PERSON_CONTEXT.find(p=>q[0].includes(p.name));if(!p)return q;const asksRole=/best known for|which role/i.test(q[0]),asksCountry=/where.*born|which country/i.test(q[0]);const role=asksCountry?p.role.replace(/australian |united states |south africa[’']s /gi,''):p.role;const context=[!asksRole?role:null,!asksCountry?'born in '+p.country:null].filter(Boolean).join('; ');if(context)q[0]=q[0].replace(p.name,p.name+' ('+context+')');q[3]=p.name+' — '+p.role+'; born in '+p.country+'. '+q[3];return q};
